"""Joins the samples with the answers already generated by Llama (nothing is generated here)."""

import json

import pandas as pd
from config import GENERATIONS_DIR, SAMPLES_DIR


def read_jsonl(path):
    with open(path, encoding="utf-8") as file:
        return [json.loads(line) for line in file]


def load_dataset(name: str) -> pd.DataFrame:
    """Return one row per sample: id, dataset, input, context (list of passages), reference, output and the
    tokens Llama used to generate the output."""
    generations = {row["id"]: row for row in read_jsonl(GENERATIONS_DIR / f"{name}_generations.jsonl")}
    rows = []

    for sample in read_jsonl(SAMPLES_DIR / f"{name}_sample.jsonl"):
        generation = generations.get(sample["id"])
        if generation is None:
            raise ValueError(f"{name}: no generated answer for sample {sample['id']}")

        rows.append(
            {
                "id": sample["id"],
                "dataset": name,
                "input": sample["question"],
                "context": sample["contexts"],
                "reference": sample["reference"],
                "output": generation["answer"],
                "generation_input_tokens": generation.get("prompt_tokens", generation.get("prompt_eval_count")),
                "generation_output_tokens": generation.get("output_tokens", generation.get("eval_count")),
            }
        )

    return pd.DataFrame(rows)
